// Образец старого Excel (.xls, BIFF8) для тестов чтения: собран из выдуманных данных (FODS → LibreOffice «MS Excel 97»).
// Лист «Packing 装箱单»: маркировка BL-901 и дата в строке 1, шапка пакинг-листа в строке 2, объединение A3:A4, формулы
// (число, SUM, CONCATENATE со строковым результатом), длинная строка, логическое значение, отрицательное и дробное
// числа, строка с пробелами; второй лист «Лист2». Файл — base64, чтобы в репозитории не было бинарных .xls.
export const XLS_B64 = '';
export const xlsBuffer = () => { const b = Buffer.from(XLS_B64, 'base64'); return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength); };
